const icons={home:'<path d="M3 11.5 12 4l9 7.5V21a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',folder:'<path d="M3 6.5h7l2 2h9v10.5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>',document:'<path d="M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7"/>',paper:'<path d="M5 4h14v16H5zM8 8h8M8 12h8M8 16h5"/>',image:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8.5" cy="9" r="1.5"/><path d="m5 18 5-5 3 3 2-2 4 4"/>',music:'<path d="M9 18V5l10-2v13M9 9l10-2"/><circle cx="6" cy="18" r="3"/><circle cx="16" cy="16" r="3"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',trash:'<path d="M4 7h16M9 7V4h6v3m3 0-1 14H7L6 7M10 11v6M14 11v6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',back:'<path d="m15 18-6-6 6-6"/>',forward:'<path d="m9 18 6-6-6-6"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',upload:'<path d="M12 16V4m-4 4 4-4 4 4M5 15v5h14v-5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',file:'<path d="M6 3h9l4 4v14H6zM14 3v5h5"/>',grid:'<rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><rect x="14" y="14" width="6" height="6" rx="1"/>',list:'<path d="M9 6h11M9 12h11M9 18h11"/><circle cx="5" cy="6" r="1"/><circle cx="5" cy="12" r="1"/><circle cx="5" cy="18" r="1"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 4v12m-5-5 5 5 5-5M5 20h14"/>',edit:'<path d="m4 20 4.5-1 10-10a2 2 0 0 0-3-3l-10 10zM14 7l3 3"/>',move:'<path d="M12 3v18M3 12h18m-4-4 4 4-4 4M8 8l-5 4 5 4"/>',expand:'<path d="M8 3H3v5M16 3h5v5M8 21H3v-5M16 21h5v-5"/>',play:'<path d="m8 5 11 7-11 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',previous:'<path d="M7 5v14M18 6l-8 6 8 6z"/>',next:'<path d="M17 5v14M6 6l8 6-8 6z"/>',volume:'<path d="M5 10v4h4l5 4V6l-5 4zM18 9a5 5 0 0 1 0 6"/>',mute:'<path d="M5 10v4h4l5 4V6l-5 4zM18 10l4 4m0-4-4 4"/>',restore:'<path d="M5 8H2V5m1 2a9 9 0 1 1-.1 9"/>',logout:'<path d="M10 4H5v16h5M14 8l4 4-4 4M8 12h10"/>'};
icons.video='<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m10 9 5 3-5 3z"/>';
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.file}</svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));

const state={csrf:null,storageConfigured:false,defaultStoragePath:'',route:'home',path:'',entries:[],selected:null,view:localStorage.getItem('archive-view')||'list',paperView:localStorage.getItem('archive-paper-view')||'table',sort:'name',audioQueue:[],audioIndex:-1,audioPath:null,pdfPage:1,pdfZoom:100,history:[''],historyIndex:0};
const $=selector=>document.querySelector(selector);
const $$=selector=>[...document.querySelectorAll(selector)];
function setTheme(value,persist=false){const theme=value==='classic'?'classic':'modern';document.documentElement.dataset.theme=theme;document.querySelector('meta[name="theme-color"]').content=theme==='classic'?'#c0c0c0':'#fafafa';if(persist)localStorage.setItem('archive-theme',theme)}
setTheme(localStorage.getItem('archive-theme'));
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const encodePath=value=>encodeURIComponent(value);
const contentUrl=(file,download=false)=>`/api/content?path=${encodePath(file.path)}${download?'&download=1':''}`;
const imageUrl=(file,variant='thumbnail')=>`/api/image?path=${encodePath(file.path)}&variant=${variant}`;
const formatSize=bytes=>bytes>=1024**4?`${(bytes/1024**4).toFixed(1)} TB`:bytes>=1024**3?`${(bytes/1024**3).toFixed(1)} GB`:bytes>=1024**2?`${(bytes/1024**2).toFixed(1)} MB`:bytes>=1024?`${(bytes/1024).toFixed(0)} KB`:`${bytes} B`;
const formatDate=value=>value?new Intl.DateTimeFormat('ko-KR',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value)):'—';
const fileType=file=>file.kind==='folder'?'Folder':file.kind==='pdf'?'PDF':file.kind==='document'?'Document':file.kind==='image'?'Image':file.kind==='audio'?'Audio':file.kind==='video'?'Video':(file.mime?.split('/')[1]||'File').toUpperCase();
const debounce=(fn,delay=220)=>{let timer;return(...args)=>{clearTimeout(timer);timer=setTimeout(()=>fn(...args),delay)}};
const uploadAccept={documents:'.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.odt,.ods,.odp,.txt,.md,.rtf,.csv,.epub',papers:'.pdf',photos:'image/*',videos:'video/*',music:'audio/*'};
function chooseFiles(){const input=$('#fileInput');input.accept=uploadAccept[state.route]||'';input.click()}

async function request(url,options={}){
  const headers={...(options.body&&!(options.body instanceof Blob)?{'Content-Type':'application/json'}:{}),...(state.csrf&&options.method&&options.method!=='GET'?{'X-CSRF-Token':state.csrf}:{}),...options.headers};
  const response=await fetch(url,{...options,headers});
  if(response.status===401){showLogin();throw new Error('로그인이 필요합니다.');}
  const body=response.headers.get('content-type')?.includes('json')?await response.json():await response.text();
  if(!response.ok)throw new Error(body.error||body||'요청을 처리하지 못했습니다.');
  return body;
}
function toast(message,type='success',timeout=2600){const node=document.createElement('div');node.className=`toast ${type==='error'?'error':''}`;node.textContent=message;$('#toastRegion').append(node);setTimeout(()=>node.remove(),timeout)}
function showRegister(){$('#app').classList.add('hidden');$('#loginScreen').classList.add('hidden');$('#registerScreen').classList.remove('hidden');$('#registerName').focus()}
function showLogin(){$('#app').classList.add('hidden');$('#registerScreen').classList.add('hidden');$('#loginScreen').classList.remove('hidden');$('#passwordInput').focus()}
function showApp(){$('#registerScreen').classList.add('hidden');$('#loginScreen').classList.add('hidden');$('#app').classList.remove('hidden');setPreviewWidth(localStorage.getItem('archive-preview-width'))}
function setAccountName(name){if(!name)return;$('#accountButton b').textContent=name;$('#accountButton .avatar').textContent=name.trim().slice(0,2).toUpperCase()}
function previewLimits(){return{min:280,max:Math.max(280,Math.min(720,innerWidth-$('.sidebar').getBoundingClientRect().width-560))}}
function setPreviewWidth(value,persist=false){const limits=previewLimits();const width=Math.round(Math.min(limits.max,Math.max(limits.min,Number(value)||352)));document.documentElement.style.setProperty('--preview',`${width}px`);const handle=$('#previewResizeHandle');handle.setAttribute('aria-valuenow',width);handle.setAttribute('aria-valuemax',limits.max);if(persist)localStorage.setItem('archive-preview-width',width);if(!localStorage.getItem('archive-pdf-preview-height'))requestAnimationFrame(()=>setPdfPreviewHeight())}
function pdfPreviewLimits(){return{min:240,max:Math.max(240,innerHeight-120)}}
function setPdfPreviewHeight(value,persist=false){const visual=$('.preview-visual.pdf');if(!visual)return;const limits=pdfPreviewLimits();const natural=Math.round(visual.clientWidth*1.414);const height=Math.round(Math.min(limits.max,Math.max(limits.min,Number(value)||natural)));visual.style.height=`${height}px`;const handle=$('#pdfPreviewResizeHandle');handle.setAttribute('aria-valuenow',height);handle.setAttribute('aria-valuemax',limits.max);if(persist)localStorage.setItem('archive-pdf-preview-height',height)}
function bindPdfPreviewResize(){const visual=$('.preview-visual.pdf'),handle=$('#pdfPreviewResizeHandle');if(!handle)return;setPdfPreviewHeight(localStorage.getItem('archive-pdf-preview-height'));handle.onpointerdown=event=>{handle.setPointerCapture(event.pointerId);document.body.classList.add('resizing-pdf-preview')};handle.onpointermove=event=>{if(handle.hasPointerCapture(event.pointerId))setPdfPreviewHeight(event.clientY-visual.getBoundingClientRect().top)};handle.onpointerup=event=>{if(!handle.hasPointerCapture(event.pointerId))return;handle.releasePointerCapture(event.pointerId);document.body.classList.remove('resizing-pdf-preview');setPdfPreviewHeight(event.clientY-visual.getBoundingClientRect().top,true)};handle.onpointercancel=()=>document.body.classList.remove('resizing-pdf-preview');handle.onkeydown=event=>{if(!['ArrowUp','ArrowDown','Home','End'].includes(event.key))return;event.preventDefault();const limits=pdfPreviewLimits();setPdfPreviewHeight(event.key==='Home'?limits.min:event.key==='End'?limits.max:visual.clientHeight+(event.key==='ArrowDown'?20:-20),true)}}
setPreviewWidth(localStorage.getItem('archive-preview-width'));

async function init(){
  const auth=await request('/api/auth/status');
  if(!auth.registered)return showRegister();
  if(!auth.authenticated)return showLogin();
  state.csrf=auth.csrf;state.storageConfigured=auth.storageConfigured;state.defaultStoragePath=auth.defaultStoragePath||'';setAccountName(auth.name);showApp();bind();if(!state.storageConfigured)return navigate('files',false);await Promise.all([navigate(location.hash.slice(1)||'home',false),updateStorage()]);
}
$('#registerForm').addEventListener('submit',async event=>{event.preventDefault();$('#registerError').textContent='';if($('#registerPassword').value!==$('#registerPasswordConfirm').value)return $('#registerError').textContent='비밀번호가 일치하지 않습니다.';try{const result=await request('/api/auth/register',{method:'POST',body:JSON.stringify({name:$('#registerName').value,password:$('#registerPassword').value})});state.csrf=result.csrf;state.storageConfigured=false;setAccountName(result.name);showApp();bind();await navigate('files',false)}catch(error){$('#registerError').textContent=error.message}});
$('#loginForm').addEventListener('submit',async event=>{event.preventDefault();$('#loginError').textContent='';try{const result=await request('/api/auth/login',{method:'POST',body:JSON.stringify({password:$('#passwordInput').value})});state.csrf=result.csrf;state.storageConfigured=result.storageConfigured;setAccountName(result.name);showApp();bind();if(!state.storageConfigured)return navigate('files',false);await Promise.all([navigate('home',false),updateStorage()])}catch(error){$('#loginError').textContent=error.message}});

let bound=false;
function bind(){
  if(bound)return;bound=true;
  $$('.nav button,[data-route]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();navigate(button.dataset.route)}));
  $('#uploadButton').onclick=chooseFiles;$('#fileInput').onchange=event=>uploadFiles(event.target.files);
  $('#searchButton').onclick=()=>openCommand();$('#closePreview').onclick=()=>closePreview();
  const resizeHandle=$('#previewResizeHandle');resizeHandle.onpointerdown=event=>{if(innerWidth<=1180)return;resizeHandle.setPointerCapture(event.pointerId);document.body.classList.add('resizing-preview')};resizeHandle.onpointermove=event=>{if(resizeHandle.hasPointerCapture(event.pointerId))setPreviewWidth(innerWidth-event.clientX)};resizeHandle.onpointerup=event=>{if(!resizeHandle.hasPointerCapture(event.pointerId))return;resizeHandle.releasePointerCapture(event.pointerId);document.body.classList.remove('resizing-preview');setPreviewWidth(innerWidth-event.clientX,true)};resizeHandle.onpointercancel=()=>document.body.classList.remove('resizing-preview');resizeHandle.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const limits=previewLimits();const current=parseInt(getComputedStyle(document.documentElement).getPropertyValue('--preview'))||352;setPreviewWidth(event.key==='Home'?limits.min:event.key==='End'?limits.max:current+(event.key==='ArrowLeft'?20:-20),true)};
  $('#mobileMenu').onclick=()=>{$('.sidebar').classList.toggle('open');syncDrawerScrim()};
  $('#drawerScrim').onclick=()=>{$('.sidebar').classList.remove('open');closePreview();syncDrawerScrim()};
  $('#accountButton').onclick=()=>openActionMenu({account:true});
  $('#backButton').onclick=()=>historyMove(-1);$('#forwardButton').onclick=()=>historyMove(1);
  document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openCommand()}if(event.key==='Escape'){closeModals();closePreview();closeVolumePopover()}if(event.key==='u'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName))chooseFiles();});
  window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)||'home',false));
  let dragDepth=0;window.addEventListener('dragenter',event=>{event.preventDefault();dragDepth++;$('#dropOverlay').classList.remove('hidden')});window.addEventListener('dragover',event=>event.preventDefault());window.addEventListener('dragleave',()=>{if(--dragDepth<=0)$('#dropOverlay').classList.add('hidden')});window.addEventListener('drop',event=>{event.preventDefault();dragDepth=0;$('#dropOverlay').classList.add('hidden');uploadFiles(event.dataTransfer.files)});
  $('#commandPalette').onclick=event=>{if(event.target===$('#commandPalette'))closeModals()};$('#commandInput').oninput=debounce(searchCommand);
  $('#formModal').onclick=event=>{if(event.target===$('#formModal')||event.target.closest('[data-close-modal]'))closeModals()};
  $('#audio').addEventListener('timeupdate',updateAudioProgress);$('#audio').addEventListener('loadedmetadata',updateAudioProgress);$('#audio').addEventListener('ended',()=>playRelative(1));
  $('#playPause').onclick=toggleAudio;$('#prevTrack').onclick=()=>playRelative(-1);$('#nextTrack').onclick=()=>playRelative(1);$('#seek').oninput=()=>{$('#audio').currentTime=Number($('#seek').value)};$('#volume').oninput=()=>{$('#audio').volume=Number($('#volume').value)};let volumeClickTimer;$('#volumeToggle').onclick=event=>{clearTimeout(volumeClickTimer);if(event.detail>1)return;if(event.detail===0)return toggleVolumePopover();volumeClickTimer=setTimeout(toggleVolumePopover,220)};$('#volumeToggle').ondblclick=event=>{event.preventDefault();clearTimeout(volumeClickTimer);const audio=$('#audio');audio.muted=!audio.muted;$('#volumeToggle').innerHTML=icon(audio.muted?'mute':'volume')};document.addEventListener('pointerdown',event=>{if(!event.target.closest('.volume'))closeVolumePopover()});
  $('#pdfClose').onclick=()=>$('#pdfModal').classList.add('hidden');$('#pdfPrev').onclick=()=>{state.pdfPage=Math.max(1,state.pdfPage-1);refreshPdf()};$('#pdfNext').onclick=()=>{state.pdfPage++;refreshPdf()};$('#pdfPage').onchange=()=>{state.pdfPage=Math.max(1,Number($('#pdfPage').value)||1);refreshPdf()};$('#pdfZoomIn').onclick=()=>{state.pdfZoom=Math.min(250,state.pdfZoom+25);refreshPdf()};$('#pdfZoomOut').onclick=()=>{state.pdfZoom=Math.max(50,state.pdfZoom-25);refreshPdf()};
  window.addEventListener('resize',debounce(()=>{if(innerWidth>720)$('.sidebar').classList.remove('open');if(innerWidth>1180)setPreviewWidth(localStorage.getItem('archive-preview-width'));setPdfPreviewHeight(localStorage.getItem('archive-pdf-preview-height'));syncDrawerScrim()},80));
}

async function navigate(route,updateHash=true){
  setAudioPlayerDocked(false);const previousRoute=state.route;state.route=state.storageConfigured?(route||'home'):'files';if(state.route==='files'&&previousRoute!=='files'){state.path='';state.history=[''];state.historyIndex=0}if(state.route==='documents'&&previousRoute!=='documents'){state.path='Documents';state.history=['Documents'];state.historyIndex=0}if(state.route==='videos')state.path='';state.selected=null;closePreview();$('.sidebar').classList.remove('open');syncDrawerScrim();
  if(updateHash&&location.hash!==`#${state.route}`)history.pushState(null,'',`#${state.route}`);
  $$('.nav button').forEach(button=>button.classList.toggle('active',button.dataset.route===state.route));
  $('#content').innerHTML='<div class="loading-state" role="status"><div class="loading-dialog"><strong>불러오는 중…</strong><div class="loading-track" aria-hidden="true"><i></i></div></div></div>';
  try{
    if(state.route==='home')await renderHome();
    else if(state.route==='papers')await renderPapers();
    else if(state.route==='photos')await renderMedia('image');
    else if(state.route==='videos')await renderMedia('video');
    else if(state.route==='music')await renderMedia('audio');
    else await renderFiles(state.route);
  }catch(error){renderError(error)}
}
function renderError(error){$('#content').innerHTML=`<div class="empty-state"><div>${icon('file')}<strong>내용을 불러오지 못했습니다.</strong><p>${esc(error.message)}</p><button class="button" id="retryButton">다시 시도</button></div></div>`;$('#retryButton').onclick=()=>navigate(state.route,false)}
function pageHead(title,description,actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div><div class="page-actions">${actions}</div></div>`}

async function renderHome(){
  const [data,storage]=await Promise.all([request('/api/dashboard'),request('/api/storage')]);
  const recent=data.recent||[],papers=data.papers||[],favorites=data.favorites||[],audio=data.audio||[];
  state.entries=[...recent,...favorites,...audio];if(!state.audioPath)state.audioQueue=audio;const usage=Math.min(100,storage.diskUsed/storage.capacity*100);
  $('#content').innerHTML=pageHead('Home','최근 작업과 즐겨찾기를 한눈에 확인하세요.',`<button class="button primary" data-upload>${icon('upload')}Upload</button>`)+`<div class="dashboard-grid"><div class="dashboard-column"><section class="panel"><div class="panel-head"><h2>Recent Files</h2><button class="text-button" data-go="recent">View all</button></div><div class="recent-list">${recent.length?recent.map(recentItem).join(''):emptyInline('최근 파일이 없습니다.')}</div></section><section class="panel"><div class="panel-head"><h2>Recent Papers</h2><button class="text-button" data-go="papers">View all</button></div><div class="paper-strip">${papers.length?papers.map(paperCard).join(''):emptyInline('등록된 논문이 없습니다.')}</div></section></div><div class="dashboard-column"><section class="panel storage-usage-panel"><div class="panel-head"><h2>Storage Usage</h2></div><div class="usage-ring"><div class="ring" style="--usage:${usage}%"><span>${Math.round(usage)}%</span></div><div><strong>${formatSize(storage.diskUsed)} / ${formatSize(storage.capacity)}</strong><small>${storage.count} files indexed</small></div></div></section><section class="panel"><div class="panel-head"><h2>Recent Audio</h2><button class="text-button" data-go="music">View all</button></div><div class="recent-list">${audio.length?audio.map(audioDashboardItem).join(''):emptyInline('최근 음원이 없습니다.')}</div><div id="homeAudioPlayerSlot" class="home-audio-slot"></div></section><section class="panel"><div class="panel-head"><h2>Favorites</h2><button class="text-button" data-go="favorites">View all</button></div><div class="recent-list">${favorites.length?favorites.map(recentItem).join(''):emptyInline('즐겨찾기가 없습니다.')}</div></section></div></div>`;
  setAudioPlayerDocked(true);bindContentItems();
}
function recentItem(file){return `<button class="recent-item" data-path="${esc(file.path)}"><span class="file-name-icon ${file.kind}">${icon(file.kind==='pdf'?'paper':file.kind)}</span><span><strong>${esc(file.name)}</strong><small>${esc(file.path)}</small></span><small>${formatDate(file.modified_at)}</small></button>`}
function audioDashboardItem(file){return `<div class="recent-item audio-dashboard-item" data-path="${esc(file.path)}"><button class="music-play" data-play-path="${esc(file.path)}" aria-label="${esc(file.name)} 바로 재생">${icon('play')}</button><span><strong>${esc(file.name)}</strong><small>${esc(file.path)}</small></span><small>${formatDate(file.accessed_at||file.modified_at)}</small></div>`}
function paperCard(paper){return `<button class="paper-card" data-paper="${esc(paper.file_path)}"><span class="paper-type">${esc(paper.venue||'Paper')} · ${esc(paper.year||'—')}</span><h3>${esc(paper.title||paper.file_path)}</h3><p>${esc(paper.authors||'저자 정보 없음')}</p></button>`}
function emptyInline(text){return `<div class="empty-state"><div><p>${esc(text)}</p></div></div>`}

async function renderFiles(scope='files'){
  if(!['files','documents'].includes(scope))state.path='';
  const result=await request(`/api/files?path=${encodePath(state.path)}&scope=${scope==='files'?'files':scope}&sort=${encodeURIComponent(state.sort)}`);if(result.setupRequired)return renderStorageSetup(result.defaultStoragePath);state.entries=result.entries;
  const names={files:['Files','모든 폴더와 파일'],documents:['Documents','PDF, Office, 텍스트 문서를 한곳에서 확인합니다.'],favorites:['Favorites','별표 표시한 항목'],recent:['Recent','최근 열어본 항목'],trash:['Trash','삭제한 항목은 직접 영구 삭제할 때까지 보관됩니다.']};const [title,description]=names[scope]||names.files;
  const actions=scope==='files'?`<button class="button" data-new-folder>${icon('plus')}New folder</button><button class="button primary" data-upload>${icon('upload')}Upload</button>`:scope==='documents'?`<button class="button" data-new-folder>${icon('plus')}New folder</button><button class="button primary" data-upload>${icon('upload')}Upload document</button>`:'';
  $('#content').innerHTML=pageHead(title,description,actions)+`${['files','documents'].includes(scope)?breadcrumb(scope):''}<div class="toolbar"><div class="toolbar-left"><input class="filter-input" id="fileFilter" placeholder="현재 폴더 검색"><select class="select" id="sortSelect"><option value="name">이름순</option><option value="-modified">최근 수정순</option><option value="-size">큰 파일순</option></select></div><div class="toolbar-right"><span class="cell">${state.entries.length} items</span><div class="segmented"><button data-view-mode="list" class="${state.view==='list'?'active':''}" aria-label="목록 보기">${icon('list')}</button><button data-view-mode="grid" class="${state.view==='grid'?'active':''}" aria-label="격자 보기">${icon('grid')}</button></div></div></div><div id="fileCollection">${renderFileCollection(state.entries,scope)}</div>`;
  $('#sortSelect').value=state.sort;$('#sortSelect').onchange=event=>{state.sort=event.target.value;renderFiles(scope)};$('#fileFilter').oninput=event=>filterCurrent(event.target.value,scope);bindContentItems(scope);updateHistoryButtons();
}
function renderStorageSetup(defaultPath){
  state.defaultStoragePath=defaultPath||state.defaultStoragePath;$('#content').innerHTML=pageHead('Files','파일을 저장할 위치를 먼저 설정하세요.')+`<form id="storageSetupForm" class="storage-setup"><h2>저장소 만들기</h2><p>Archive가 실행되는 서버의 디렉터리를 사용합니다.</p><label class="storage-choice"><input type="radio" name="mode" value="managed" checked><span><strong>기본 폴더 생성</strong><small>${esc(state.defaultStoragePath)}</small></span></label><label class="storage-choice"><input type="radio" name="mode" value="existing"><span><strong>기존 로컬 경로 연결</strong><small>이미 존재하며 읽기·쓰기가 가능한 절대 경로</small></span></label><label id="storagePathLabel" class="storage-path hidden">로컬 경로<input id="storagePath" name="path" placeholder="/mnt/my-files" autocomplete="off"></label><p class="storage-note">Docker에서는 컨테이너에 마운트된 경로만 연결할 수 있습니다.</p><p id="storageSetupError" class="form-error" role="alert"></p><button class="button primary" type="submit">저장소 생성</button></form>`;
  const pathLabel=$('#storagePathLabel'),pathInput=$('#storagePath');$$('[name="mode"]').forEach(input=>input.onchange=()=>{const existing=input.form.elements.mode.value==='existing';pathLabel.classList.toggle('hidden',!existing);pathInput.required=existing;if(existing)pathInput.focus()});
  $('#storageSetupForm').onsubmit=async event=>{event.preventDefault();$('#storageSetupError').textContent='';const data=new FormData(event.currentTarget);try{await request('/api/storage/setup',{method:'POST',body:JSON.stringify({mode:data.get('mode'),path:data.get('path')})});state.storageConfigured=true;toast('저장소를 설정했습니다.');await Promise.all([navigate('home'),updateStorage()])}catch(error){$('#storageSetupError').textContent=error.message}};
}
function breadcrumb(scope){const documents=scope==='documents',root=documents?'Documents':'',relative=documents?state.path.slice(root.length).replace(/^\//,''):state.path,parts=relative?relative.split('/'):[];return `<div class="breadcrumb"><button data-folder="${root}">${documents?'Documents':'My Archive'}</button>${parts.map((part,index)=>`<i>/</i><button data-folder="${esc([root,...parts.slice(0,index+1)].filter(Boolean).join('/'))}">${esc(part)}</button>`).join('')}</div>`}
function renderFileCollection(entries,scope){
  if(!entries.length)return emptyInline(scope==='trash'?'휴지통이 비어 있습니다.':scope==='documents'?'문서 파일이 없습니다.':'이 폴더가 비어 있습니다.');
  if(state.view==='grid')return `<div class="file-grid">${entries.map(fileCard).join('')}</div>`;
  return `<div class="file-table"><div class="file-row header"><div>Name</div><div>Type</div><div>Size</div><div>Modified</div><div></div></div>${entries.map(fileRow).join('')}</div>`;
}
function fileRow(file){return `<div class="file-row ${state.selected?.path===file.path?'selected':''}" data-path="${esc(file.path)}"><div class="file-name"><span class="file-name-icon ${file.kind}">${icon(file.kind==='pdf'?'paper':file.kind)}</span><span><strong>${esc(file.name)}</strong><small>${esc(file.path)}</small></span></div><div class="cell">${fileType(file)}</div><div class="cell">${file.kind==='folder'?'—':formatSize(file.size)}</div><div class="cell">${file.trashed_at?formatDate(file.trashed_at):formatDate(file.modified_at)}</div><button class="row-menu" data-menu="${esc(file.path)}" aria-label="파일 메뉴">${icon('more')}</button></div>`}
function fileCard(file){const visual=file.kind==='image'?`<img src="${imageUrl(file)}" alt="" loading="lazy">`:icon(file.kind==='pdf'?'paper':file.kind);return `<div class="file-card ${state.selected?.path===file.path?'selected':''}" data-path="${esc(file.path)}"><div class="file-card-preview">${visual}</div><strong>${esc(file.name)}</strong><small>${fileType(file)} · ${file.kind==='folder'?'—':formatSize(file.size)}</small><button class="star-button ${file.favorite?'active':''}" data-favorite="${esc(file.path)}" aria-label="즐겨찾기" aria-pressed="${file.favorite}">${icon('star')}</button></div>`}
function filterCurrent(query,scope){const value=query.toLocaleLowerCase();const entries=state.entries.filter(file=>file.name.toLocaleLowerCase().includes(value));$('#fileCollection').innerHTML=renderFileCollection(entries,scope);bindContentItems(scope)}

async function renderPapers(){
  state.path='Documents/Papers';
  const result=await request('/api/papers');state.entries=result.papers.map(paper=>({path:paper.file_path,name:paper.title,kind:'pdf',mime:'application/pdf',size:paper.size,modified_at:paper.modified_at,favorite:paper.favorite,paper}));
  $('#content').innerHTML=pageHead('Papers','PDF 논문과 서지 정보를 함께 관리합니다.',`<button class="button primary" data-upload>${icon('upload')}Add paper</button>`)+`<div class="paper-filters"><input id="paperSearch" placeholder="제목 또는 저자 검색"><input id="paperYear" type="number" placeholder="연도" min="1800" max="2100"><input id="paperTag" placeholder="태그"><input id="paperVenue" placeholder="Conference / Journal"><div class="segmented"><button data-paper-view="table" class="${state.paperView==='table'?'active':''}">${icon('list')}</button><button data-paper-view="card" class="${state.paperView==='card'?'active':''}">${icon('grid')}</button></div></div><div id="paperCollection">${renderPaperCollection(state.entries)}</div>`;
  const refresh=debounce(async()=>{const params=new URLSearchParams({q:$('#paperSearch').value,year:$('#paperYear').value,tag:$('#paperTag').value,venue:$('#paperVenue').value});const data=await request(`/api/papers?${params}`);state.entries=data.papers.map(paper=>({path:paper.file_path,name:paper.title,kind:'pdf',mime:'application/pdf',size:paper.size,modified_at:paper.modified_at,favorite:paper.favorite,paper}));$('#paperCollection').innerHTML=renderPaperCollection(state.entries);bindContentItems('papers')});$$('.paper-filters input').forEach(input=>input.oninput=refresh);bindContentItems('papers');
}
function renderPaperCollection(entries){if(!entries.length)return emptyInline('조건에 맞는 논문이 없습니다.');if(state.paperView==='card')return `<div class="file-grid">${entries.map(file=>`<div class="paper-card" data-path="${esc(file.path)}"><span class="paper-type">${esc(file.paper.venue||'Paper')} · ${esc(file.paper.year||'—')}</span><h3>${esc(file.paper.title)}</h3><p>${esc(file.paper.authors||'저자 정보 없음')}</p><div class="tags">${(file.paper.tags||[]).slice(0,3).map(tag=>`<span class="tag">${esc(tag)}</span>`).join('')}</div></div>`).join('')}</div>`;return `<div class="file-table paper-table"><div class="file-row header"><div class="paper-column-header">Title<span class="paper-column-resizer" data-paper-resize role="separator" aria-label="제목과 저자 열 너비 조절" aria-orientation="vertical" aria-valuemin="30" aria-valuemax="75" tabindex="0"></span></div><div>Authors</div><div>Year</div><div>Venue</div><div></div></div>${entries.map(file=>`<div class="file-row" data-path="${esc(file.path)}"><div class="file-name"><span class="file-name-icon pdf">${icon('paper')}</span><span><strong>${esc(file.paper.title)}</strong></span></div><div class="cell">${esc(file.paper.authors||'—')}</div><div class="cell">${esc(file.paper.year||'—')}</div><div class="cell">${esc(file.paper.venue||'—')}</div><button class="star-button ${file.favorite?'active':''}" data-favorite="${esc(file.path)}">${icon('star')}</button></div>`).join('')}</div>`}
function setPaperColumnRatio(value,persist=false){const ratio=Math.max(.3,Math.min(.75,Number(value)||.6));document.documentElement.style.setProperty('--paper-column-ratio',ratio);document.documentElement.style.setProperty('--paper-title-fr',`${ratio*100}fr`);document.documentElement.style.setProperty('--paper-authors-fr',`${(1-ratio)*100}fr`);$('[data-paper-resize]')?.setAttribute('aria-valuenow',Math.round(ratio*100));if(persist)localStorage.setItem('archive-paper-column-ratio',ratio)}
function bindPaperColumnResize(){const handle=$('[data-paper-resize]');if(!handle)return;setPaperColumnRatio(localStorage.getItem('archive-paper-column-ratio'));let startX,startRatio,pairWidth;handle.onpointerdown=event=>{const cells=handle.closest('.file-row').children;startX=event.clientX;pairWidth=cells[0].getBoundingClientRect().width+cells[1].getBoundingClientRect().width;startRatio=cells[0].getBoundingClientRect().width/pairWidth;handle.setPointerCapture(event.pointerId);document.body.classList.add('resizing-paper-columns')};handle.onpointermove=event=>{if(handle.hasPointerCapture(event.pointerId))setPaperColumnRatio(startRatio+(event.clientX-startX)/pairWidth)};handle.onpointerup=event=>{if(!handle.hasPointerCapture(event.pointerId))return;handle.releasePointerCapture(event.pointerId);document.body.classList.remove('resizing-paper-columns');setPaperColumnRatio(getComputedStyle(document.documentElement).getPropertyValue('--paper-column-ratio'),true)};handle.onpointercancel=()=>document.body.classList.remove('resizing-paper-columns');handle.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const current=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--paper-column-ratio'))||.6;setPaperColumnRatio(event.key==='Home'?.3:event.key==='End'?.75:current+(event.key==='ArrowRight'?.03:-.03),true)}}

async function renderMedia(kind){
  const data=await request(`/api/files?scope=media&kind=${kind}`),files=data.entries||[];state.entries=files;
  if(kind==='image'){$('#content').innerHTML=pageHead('Photos','이미지 원본과 캐시된 미리보기를 분리해 표시합니다.',`<button class="button primary" data-upload>${icon('upload')}Upload</button>`)+(files.length?`<div class="photo-grid">${files.map(file=>`<button class="photo-card" data-path="${esc(file.path)}"><img src="${imageUrl(file)}" loading="lazy" alt="${esc(file.name)}">${file.favorite?`<span class="star-button active">${icon('star')}</span>`:''}</button>`).join('')}</div>`:emptyInline('이미지가 없습니다.'));}
  else if(kind==='video'){$('#content').innerHTML=pageHead('Videos','브라우저에서 바로 미리볼 수 있는 비디오 라이브러리입니다.',`<button class="button primary" data-upload>${icon('upload')}Upload</button>`)+(files.length?`<div id="fileCollection">${renderFileCollection(files,'videos')}</div>`:emptyInline('비디오 파일이 없습니다.'));}
  else{$('#content').innerHTML=pageHead('Music','브라우저에서 바로 재생할 수 있는 오디오 라이브러리입니다.',`<button class="button primary" data-upload>${icon('upload')}Upload</button>`)+(files.length?`<div class="file-table music-list"><div class="file-row header"><div></div><div>Name</div><div>Type</div><div>Modified</div><div></div></div>${files.map((file,index)=>`<div class="file-row" data-path="${esc(file.path)}"><button class="music-play" data-play-index="${index}">${icon('play')}</button><div class="file-name"><span class="file-name-icon audio">${icon('music')}</span><span><strong>${esc(file.name)}</strong><small>${esc(file.path)}</small></span></div><div class="cell">${fileType(file)}</div><div class="cell">${formatDate(file.modified_at)}</div><button class="row-menu" data-menu="${esc(file.path)}">${icon('more')}</button></div>`).join('')}</div>`:emptyInline('오디오 파일이 없습니다.'));state.audioQueue=files;state.audioIndex=files.findIndex(file=>file.path===state.audioPath);}
  bindContentItems(kind==='image'?'photos':kind==='video'?'videos':'music');
}

function bindContentItems(scope=state.route){
  $$('[data-upload]').forEach(button=>button.onclick=chooseFiles);$$('[data-new-folder]').forEach(button=>button.onclick=()=>folderModal());$$('[data-go]').forEach(button=>button.onclick=()=>navigate(button.dataset.go));
  $$('[data-folder]').forEach(button=>button.onclick=()=>openFolder(button.dataset.folder));
  $$('[data-path]').forEach(node=>{node.onclick=event=>{if(event.target.closest('[data-menu],[data-favorite],[data-play-index],[data-play-path]'))return;selectPath(node.dataset.path)};node.ondblclick=()=>{const file=findFile(node.dataset.path);if(file?.kind==='folder')openFolder(file.path);else if(file?.kind==='pdf')openPdf(file);else if(file?.kind==='audio')playFile(file)}});
  $$('[data-menu]').forEach(button=>button.onclick=event=>{event.stopPropagation();openActionMenu(findFile(button.dataset.menu))});$$('[data-favorite]').forEach(button=>button.onclick=event=>{event.stopPropagation();toggleFavorite(findFile(button.dataset.favorite))});
  $$('[data-view-mode]').forEach(button=>button.onclick=()=>{state.view=button.dataset.viewMode;localStorage.setItem('archive-view',state.view);renderFiles(scope)});$$('[data-paper-view]').forEach(button=>button.onclick=()=>{state.paperView=button.dataset.paperView;localStorage.setItem('archive-paper-view',state.paperView);$('#paperCollection').innerHTML=renderPaperCollection(state.entries);bindContentItems('papers')});
  $$('[data-play-index]').forEach(button=>button.onclick=event=>{event.stopPropagation();playIndex(Number(button.dataset.playIndex))});
  $$('[data-play-path]').forEach(button=>button.onclick=event=>{event.stopPropagation();playFile(findFile(button.dataset.playPath))});
  $$('[data-paper]').forEach(button=>button.onclick=()=>selectPaper(button.dataset.paper));
  if(scope==='papers')bindPaperColumnResize();
}
function findFile(pathValue){return state.entries.find(file=>file.path===pathValue)||null}
async function openFolder(folder,record=true){if(record){state.history=state.history.slice(0,state.historyIndex+1);state.history.push(folder);state.historyIndex++}const scope=state.route==='documents'?'documents':'files';closePreview();state.path=folder;state.route=scope;if(location.hash!==`#${scope}`)history.pushState(null,'',`#${scope}`);await renderFiles(scope)}
function historyMove(direction){const next=state.historyIndex+direction;if(next<0||next>=state.history.length)return;state.historyIndex=next;state.path=state.history[next];renderFiles(state.route==='documents'?'documents':'files')}
function updateHistoryButtons(){$('#backButton').disabled=state.historyIndex<=0;$('#forwardButton').disabled=state.historyIndex>=state.history.length-1}

function selectPath(pathValue){const file=findFile(pathValue);if(!file)return;state.selected=file;showPreview(file);document.querySelectorAll('[data-path]').forEach(node=>node.classList.toggle('selected',node.dataset.path===pathValue))}
async function selectPaper(pathValue){if(state.route!=='papers'){await navigate('papers');}const file=findFile(pathValue);if(file)selectPath(pathValue)}
function syncDrawerScrim(){const visible=(innerWidth<=720&&$('.sidebar').classList.contains('open'))||(innerWidth<=1180&&$('#previewPanel').classList.contains('open'));$('#drawerScrim').classList.toggle('show',visible)}
function closePreview(){$('#previewPanel').classList.remove('open');state.selected=null;syncDrawerScrim()}
function showPreview(file){
  $('#previewPanel').classList.add('open');syncDrawerScrim();const paper=state.route==='documents'?null:file.paper||file.paper===null?file.paper:null;
  const available=state.route!=='trash';
  let visual=`<div class="preview-visual file">${icon(file.kind==='folder'?'folder':file.kind==='audio'?'music':'file')}</div>`;
  if(file.kind==='image'&&available)visual=`<div class="preview-visual"><img src="${imageUrl(file,'preview')}" alt="${esc(file.name)}"></div>`;
  if(file.kind==='video'&&available)visual=`<div class="preview-visual video"><video src="${contentUrl(file)}" controls preload="metadata"></video></div>`;
  if(file.kind==='pdf'&&available)visual=`<div class="preview-visual pdf"><iframe src="${contentUrl(file)}#page=1&view=Fit&toolbar=0" title="${esc(file.name)} PDF 미리보기"></iframe><div id="pdfPreviewResizeHandle" class="pdf-preview-resize-handle" role="separator" aria-label="PDF 미리보기 높이 조절" aria-orientation="horizontal" aria-valuemin="240" tabindex="0"></div></div>`;
  if(file.kind==='audio')visual=`<div class="preview-visual file"><button class="music-play" id="previewPlay">${icon('play')}</button></div>`;
  $('#previewBody').innerHTML=visual+`<div class="preview-info"><div class="preview-title"><div><h2>${esc(paper?.title||file.name)}</h2><p>${esc(fileType(file))} · ${file.kind==='folder'?'Folder':formatSize(file.size||0)}</p></div><button class="star-button ${file.favorite?'active':''}" id="previewFavorite">${icon('star')}</button></div><div class="preview-actions">${file.kind==='folder'&&available?`<button class="button primary" id="openFolder">${icon('folder')}Open folder</button>`:''}${file.kind!=='folder'&&available?`<a class="button" href="${contentUrl(file,true)}" download>${icon('download')}Download</a>`:''}${file.kind==='pdf'&&available?`<button class="button primary" id="openPdf">${icon('expand')}Open PDF</button>`:''}${file.kind==='image'&&available?`<button class="button primary" id="openImage">${icon('expand')}Fullscreen</button>`:''}${file.kind==='audio'&&available?`<button class="button primary" id="playAudio">${icon('play')}Play</button>`:''}${available?paper?`<button class="button" id="editPaperTitle">${icon('edit')}논문 제목 변경</button>`:`<button class="button" id="renameFile">${icon('edit')}${file.kind==='folder'?'폴더명':'파일명'} 변경</button>`:''}<button class="button wide-action" id="moreActions">${icon('more')}More actions</button></div>${paper?paperQuickEditor(paper):''}<dl class="meta-list">${paper?paperMetadata(paper,file):fileMetadata(file)}</dl>${paper?.memo?`<div class="memo">${esc(paper.memo)}</div>`:''}</div>`;
  $('#previewFavorite').onclick=()=>toggleFavorite(file);$('#openFolder')?.addEventListener('click',()=>openFolder(file.path));$('#editPaperTitle')?.addEventListener('click',()=>paperModal(file));$('#renameFile')?.addEventListener('click',()=>renameModal(file));$('#moreActions').onclick=()=>openActionMenu(file);$('#openPdf')?.addEventListener('click',()=>openPdf(file));$('#openImage')?.addEventListener('click',()=>openImage(file));$('#playAudio')?.addEventListener('click',()=>playFile(file));$('#previewPlay')?.addEventListener('click',()=>playFile(file));$('#paperQuickEdit')?.addEventListener('submit',event=>savePaperQuickEdit(event,file,paper));$('#paperAdvancedEdit')?.addEventListener('click',()=>paperModal(file));bindPdfPreviewResize();
}
function fileMetadata(file){return `<div class="meta-row"><dt>File name</dt><dd>${esc(file.name)}</dd></div><div class="meta-row"><dt>Location</dt><dd>/${esc(file.path)}</dd></div><div class="meta-row"><dt>Type</dt><dd>${esc(file.mime||fileType(file))}</dd></div><div class="meta-row"><dt>Size</dt><dd>${file.kind==='folder'?'—':formatSize(file.size||0)}</dd></div>${file.width&&file.height?`<div class="meta-row"><dt>Resolution</dt><dd>${file.width} × ${file.height}</dd></div>`:''}<div class="meta-row"><dt>Created</dt><dd>${formatDate(file.created_at)}</dd></div><div class="meta-row"><dt>Modified</dt><dd>${formatDate(file.modified_at)}</dd></div>`}
function paperMetadata(paper,file){return `<div class="meta-row"><dt>Authors</dt><dd>${esc(paper.authors||'—')}</dd></div><div class="meta-row"><dt>Published</dt><dd>${esc(paper.venue||'—')} · ${esc(paper.year||'—')}</dd></div><div class="meta-row"><dt>DOI</dt><dd>${esc(paper.doi||'—')}</dd></div><div class="meta-row"><dt>Tags</dt><dd><div class="tags">${(paper.tags||[]).map(tag=>`<span class="tag">${esc(tag)}</span>`).join('')||'—'}</div></dd></div><div class="meta-row"><dt>File path</dt><dd>/${esc(file.path)}</dd></div><div class="meta-row"><dt>Added</dt><dd>${formatDate(paper.added_date)}</dd></div>`}
function paperQuickEditor(paper){return `<details class="paper-quick-editor"><summary>${icon('edit')}저자 · 연도 · 베뉴 수정</summary><form id="paperQuickEdit"><label>Authors<input name="authors" value="${esc(paper.authors||'')}" placeholder="저자 이름"></label><div class="paper-quick-row"><label>Year<input name="year" type="number" min="1800" max="2100" value="${esc(paper.year||'')}" placeholder="연도"></label><label>Conference / Journal<input name="venue" value="${esc(paper.venue||'')}" placeholder="학회 또는 저널"></label></div><div class="paper-quick-actions"><button class="button primary" type="submit">저장</button><button class="button" id="paperAdvancedEdit" type="button">전체 메타데이터</button></div></form></details>`}
async function savePaperQuickEdit(event,file,paper){event.preventDefault();const form=event.currentTarget,submit=form.querySelector('[type="submit"]'),data=new FormData(form);submit.disabled=true;try{const authors=String(data.get('authors')||'').trim(),venue=String(data.get('venue')||'').trim(),year=Number(data.get('year'))||null;await request('/api/papers',{method:'PUT',body:JSON.stringify({file_path:file.path,title:paper.title,authors,venue,year,doi:paper.doi,tags:paper.tags||[],memo:paper.memo})});Object.assign(paper,{authors,venue,year});$('.meta-list').innerHTML=paperMetadata(paper,file);form.closest('details').open=false;toast('논문 정보를 저장했습니다.')}catch(error){toast(error.message,'error')}finally{submit.disabled=false}}

function openActionMenu(file){
  if(file?.account){showModal({title:'옵션',description:'현재 개인 워크스페이스',fields:`<label>디자인 테마<select id="themeSelect"><option value="modern">Modern</option><option value="classic">Windows 98 Classic</option></select></label><p class="cell">테마 설정은 이 브라우저에 저장됩니다.</p>`,submit:'로그아웃',onSubmit:async()=>{await request('/api/auth/logout',{method:'POST'});closeModals();showLogin()}});$('#themeSelect').value=document.documentElement.dataset.theme;$('#themeSelect').onchange=event=>{setTheme(event.target.value,true);toast(event.target.value==='classic'?'Windows 98 테마를 적용했습니다.':'Modern 테마를 적용했습니다.')};return}
  if(!file)return;const trash=state.route==='trash';
  const fields=`<div class="action-list"><button type="button" class="button wide" data-action="favorite">${icon('star')}${file.favorite?'즐겨찾기 해제':'즐겨찾기'}</button>${!trash?`${file.paper?`<button type="button" class="button wide" data-action="paper">${icon('edit')}논문 제목 · 정보 변경</button>`:''}<button type="button" class="button wide" data-action="rename">${icon('edit')}${file.kind==='folder'?'폴더명':'실제 파일명'} 변경</button><button type="button" class="button wide" data-action="move">${icon('move')}이동</button>${file.kind!=='folder'?`<a class="button wide" href="${contentUrl(file,true)}" download>${icon('download')}다운로드</a>`:''}<button type="button" class="button danger wide" data-action="delete">${icon('trash')}휴지통으로 이동</button>`:`<button type="button" class="button wide" data-action="restore">${icon('restore')}복원</button><button type="button" class="button danger wide" data-action="permanent">${icon('trash')}영구 삭제</button>`}</div>`;
  showModal({title:file.name,description:file.path,fields,hideSubmit:true});
  $$('[data-action]').forEach(button=>button.onclick=()=>{const action=button.dataset.action;closeModals();if(action==='favorite')toggleFavorite(file);if(action==='paper')paperModal(file);if(action==='rename')renameModal(file);if(action==='move')moveModal(file);if(action==='delete')deleteFile(file);if(action==='restore')restoreFile(file);if(action==='permanent')permanentDelete(file)});
}
function showModal({title,description='',fields='',submit='저장',hideSubmit=false,onSubmit}){$('#modalTitle').textContent=title;$('#modalDescription').textContent=description;$('#modalFields').innerHTML=fields;$('#modalSubmit').textContent=submit;$('#modalSubmit').classList.toggle('hidden',hideSubmit);$('#modalError').textContent='';$('#formModal').classList.remove('hidden');setTimeout(()=>$('#modalFields input')?.focus(),0);$('#formModalCard').onsubmit=async event=>{event.preventDefault();if(!onSubmit)return;try{await onSubmit(new FormData(event.currentTarget));closeModals()}catch(error){$('#modalError').textContent=error.message}}}
function closeModals(){$('#formModal').classList.add('hidden');$('#commandPalette').classList.add('hidden')}
function folderModal(){showModal({title:'새 폴더',description:`/${state.path}`,fields:'<label>폴더 이름<input name="name" required maxlength="255" placeholder="새 폴더"></label>',submit:'만들기',onSubmit:async data=>{await request('/api/folders',{method:'POST',body:JSON.stringify({path:state.path,name:data.get('name')})});toast('폴더를 만들었습니다.');await renderFiles(state.route==='documents'?'documents':'files')}})}
function renameModal(file){showModal({title:file.kind==='folder'?'폴더명 변경':'실제 파일명 변경',description:file.path,fields:`<label>새 이름<input name="name" required maxlength="255" value="${esc(file.name)}"></label>${file.kind!=='folder'?'<small class="cell">파일 형식을 보호하기 위해 기존 확장자는 유지됩니다.</small>':''}`,onSubmit:async data=>{await request('/api/files/rename',{method:'POST',body:JSON.stringify({path:file.path,name:data.get('name')})});toast(file.kind==='folder'?'폴더명을 변경했습니다.':'파일명을 변경했습니다.');await navigate(state.route,false)}})}
function moveModal(file){showModal({title:'이동',description:file.path,fields:`<label>대상 폴더 경로<input name="destination" placeholder="예: Research/Papers"></label><small class="cell">최상위 폴더는 비워 두세요.</small>`,submit:'이동',onSubmit:async data=>{await request('/api/files/move',{method:'POST',body:JSON.stringify({path:file.path,destination:data.get('destination')})});toast('항목을 이동했습니다.');await navigate(state.route,false)}})}
function paperModal(file){const paper=file.paper||{};showModal({title:'논문 메타데이터',description:`실제 파일명: ${file.name}`,fields:`<label>Title<input name="title" value="${esc(paper.title||file.name.replace(/\.pdf$/i,''))}" required></label><label>Authors<input name="authors" value="${esc(paper.authors||'')}"></label><label>Conference / Journal<input name="venue" value="${esc(paper.venue||'')}"></label><label>Year<input name="year" type="number" min="1800" max="2100" value="${esc(paper.year||'')}"></label><label>DOI<input name="doi" value="${esc(paper.doi||'')}"></label><label>Tags<input name="tags" value="${esc((paper.tags||[]).join(', '))}" placeholder="RAG, LLM, Robotics"></label><label>Memo<textarea name="memo">${esc(paper.memo||'')}</textarea></label>`,onSubmit:async data=>{const payload=Object.fromEntries(data);payload.file_path=file.path;payload.tags=String(payload.tags).split(',').map(tag=>tag.trim()).filter(Boolean);await request('/api/papers',{method:'PUT',body:JSON.stringify(payload)});toast('논문 정보를 저장했습니다.');await navigate(state.route,false)}})}
async function deleteFile(file){if(!confirm(`“${file.name}”을(를) 휴지통으로 이동할까요?`))return;await request('/api/files',{method:'DELETE',body:JSON.stringify({path:file.path})});toast('휴지통으로 이동했습니다.');closePreview();await navigate(state.route,false)}
async function restoreFile(file){await request('/api/files/restore',{method:'POST',body:JSON.stringify({path:file.path})});toast('항목을 복원했습니다.');closePreview();await renderFiles('trash')}
async function permanentDelete(file){if(!confirm(`“${file.name}”을(를) 영구 삭제할까요? 이 작업은 되돌릴 수 없습니다.`))return;await request('/api/files/permanent',{method:'DELETE',body:JSON.stringify({path:file.path})});toast('영구 삭제했습니다.');closePreview();await renderFiles('trash')}
async function toggleFavorite(file){
  const previous=file.favorite;file.favorite=!previous;syncFavoriteButtons(file);
  try{await request('/api/files/favorite',{method:'POST',body:JSON.stringify({path:file.path,value:file.favorite})});toast(file.favorite?'즐겨찾기에 추가했습니다.':'즐겨찾기에서 제거했습니다.');if(state.route==='favorites')await renderFiles('favorites')}
  catch(error){file.favorite=previous;syncFavoriteButtons(file);toast(error.message,'error')}
}
function syncFavoriteButtons(file){$$('[data-favorite]').filter(button=>button.dataset.favorite===file.path).forEach(button=>{button.classList.toggle('active',file.favorite);button.setAttribute('aria-pressed',String(file.favorite))});const preview=$('#previewFavorite');if(preview){preview.classList.toggle('active',file.favorite);preview.setAttribute('aria-pressed',String(file.favorite))}}

function uploadFiles(fileList){const files=[...fileList];if(!files.length)return;const allowedRoute=['files','documents','papers','photos','videos','music'].includes(state.route);if(!allowedRoute)navigate('files');files.forEach(file=>uploadOne(file));$('#fileInput').value=''}
function uploadOne(file){
  const node=document.createElement('div');node.className='toast upload-toast';node.innerHTML=`<div><span>${esc(file.name)}</span><b>0%</b></div><div class="upload-progress"><i></i></div>`;$('#toastRegion').append(node);
  const xhr=new XMLHttpRequest();xhr.open('PUT',`/api/files/upload?path=${encodePath(state.path)}&name=${encodeURIComponent(file.name)}`);xhr.setRequestHeader('Content-Type',file.type||'application/octet-stream');xhr.setRequestHeader('X-CSRF-Token',state.csrf);xhr.upload.onprogress=event=>{if(!event.lengthComputable)return;const progress=Math.round(event.loaded/event.total*100);node.querySelector('b').textContent=`${progress}%`;node.querySelector('i').style.width=`${progress}%`};xhr.onload=async()=>{if(xhr.status>=200&&xhr.status<300){node.querySelector('b').textContent='완료';setTimeout(()=>node.remove(),1100);await updateStorage();if(['files','documents','papers','photos','videos','music'].includes(state.route))await navigate(state.route,false)}else{node.classList.add('error');node.querySelector('b').textContent='실패';try{toast(JSON.parse(xhr.responseText).error,'error')}catch{toast('업로드하지 못했습니다.','error')}}};xhr.onerror=()=>{node.classList.add('error');node.querySelector('b').textContent='오류'};xhr.send(file);
}

function openPdf(file){state.pdfPage=1;state.pdfZoom=100;$('#pdfTitle').textContent=file.paper?.title||file.name;$('#pdfDownload').href=contentUrl(file,true);$('#pdfModal').classList.remove('hidden');state.pdfFile=file;refreshPdf()}
function refreshPdf(){$('#pdfPage').value=state.pdfPage;$('#pdfZoomLabel').textContent=`${state.pdfZoom}%`;$('#pdfFrame').src=`${contentUrl(state.pdfFile)}#page=${state.pdfPage}&zoom=${state.pdfZoom}&toolbar=0`}
function openImage(file){const image=window.open(imageUrl(file,'preview'),'_blank','noopener,noreferrer');if(!image)toast('팝업 차단을 해제해 주세요.','error')}
function playFile(file){let index=state.audioQueue.findIndex(item=>item.path===file.path);if(index<0){state.audioQueue=[file,...state.entries.filter(item=>item.kind==='audio'&&item.path!==file.path)];index=0}playIndex(index)}
function setAudioPlayerDocked(docked){const player=$('#audioPlayer'),slot=$('#homeAudioPlayerSlot');(docked&&slot?slot:$('#app')).append(player);player.classList.toggle('home-docked',Boolean(docked&&slot));$('#app').classList.toggle('player-docked',Boolean(docked&&slot))}
function playIndex(index){const file=state.audioQueue[index];if(!file)return;state.audioIndex=index;state.audioPath=file.path;const audio=$('#audio');audio.src=contentUrl(file);audio.volume=Number($('#volume').value);audio.play().catch(()=>{});$('#audioName').textContent=file.name;$('#audioPath').textContent=file.path;$('#audioPlayer').classList.remove('hidden');$('#app').classList.add('has-player');$('#previewPanel').classList.add('has-player');$('#playPause').innerHTML=icon('pause')}
function toggleAudio(){const audio=$('#audio');if(!audio.src)return;if(audio.paused){audio.play();$('#playPause').innerHTML=icon('pause')}else{audio.pause();$('#playPause').innerHTML=icon('play')}}
function playRelative(offset){if(!state.audioQueue.length)return;playIndex((state.audioIndex+offset+state.audioQueue.length)%state.audioQueue.length)}
function updateAudioProgress(){const audio=$('#audio');$('#seek').max=Number.isFinite(audio.duration)?audio.duration:0;$('#seek').value=audio.currentTime||0;$('#currentTime').textContent=time(audio.currentTime);$('#duration').textContent=time(audio.duration)}
function toggleVolumePopover(){const popover=$('#volumePopover'),open=popover.classList.toggle('hidden');$('#volumeToggle').setAttribute('aria-expanded',String(!open));if(!open)$('#volume').focus()}
function closeVolumePopover(){$('#volumePopover').classList.add('hidden');$('#volumeToggle').setAttribute('aria-expanded','false')}
function time(seconds){if(!Number.isFinite(seconds))return'0:00';return`${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}`}

function openCommand(){closeModals();$('#commandPalette').classList.remove('hidden');$('#commandInput').value='';$('#commandResults').innerHTML='<div class="command-group"><h3>Quick actions</h3><button class="command-item" data-command="upload">'+icon('upload')+'<span><strong>Upload files</strong><small>현재 폴더에 파일 추가</small></span><kbd>U</kbd></button><button class="command-item" data-command="folder">'+icon('plus')+'<span><strong>New folder</strong><small>현재 위치에 폴더 생성</small></span></button></div>';$('#commandInput').focus();$$('[data-command]').forEach(button=>button.onclick=()=>{closeModals();button.dataset.command==='upload'?chooseFiles():folderModal()})}
async function searchCommand(){const query=$('#commandInput').value.trim();if(!query)return openCommand();try{const data=await request(`/api/search?q=${encodeURIComponent(query)}`);const labels={papers:'Papers',files:'Files',folders:'Folders'};$('#commandResults').innerHTML=Object.entries(data.groups).map(([group,items])=>items.length?`<section class="command-group"><h3>${labels[group]}</h3>${items.map(item=>{const pathValue=item.file_path||item.path;const name=item.title||item.name;return `<button class="command-item" data-result="${esc(pathValue)}" data-kind="${group}">${icon(group==='papers'?'paper':item.kind||'file')}<span><strong>${esc(name)}</strong><small>${esc(item.authors||pathValue)}</small></span></button>`}).join('')}</section>`:'').join('')||emptyInline('검색 결과가 없습니다.');$$('[data-result]').forEach(button=>button.onclick=async()=>{closeModals();const kind=button.dataset.kind;if(kind==='papers'){await navigate('papers');selectPath(button.dataset.result)}else{const target=button.dataset.result;const parent=target.includes('/')?target.slice(0,target.lastIndexOf('/')):'';await openFolder(parent);selectPath(target)}})}catch(error){$('#commandResults').innerHTML=emptyInline(error.message)}}

async function updateStorage(){try{const data=await request('/api/storage');$('#storageLabel').textContent=`${formatSize(data.diskUsed)} / ${formatSize(data.capacity)}`;$('#storageCount').textContent=`${data.count} files indexed`;$('#storageBar').style.width=`${Math.min(100,data.diskUsed/data.capacity*100)}%`}catch{}}

init().catch(error=>{console.error(error);showLogin()});
